import{_ as i,o as n,c as t,a2 as u}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Ufafanuzi na Asili ya Asili ya Kitu cha Nanga","description":"","frontmatter":{},"headers":[],"relativePath":"sw/02-锚点本源定义与本质.md","filePath":"sw/02-锚点本源定义与本质.md","lastUpdated":1789183869000}'),h={name:"sw/02-锚点本源定义与本质.md"};function s(o,a,e,k,w,d){return n(),t("div",null,[...a[0]||(a[0]=[u('<h1 id="ufafanuzi-na-asili-ya-asili-ya-kitu-cha-nanga" tabindex="-1">Ufafanuzi na Asili ya Asili ya Kitu cha Nanga <a class="header-anchor" href="#ufafanuzi-na-asili-ya-asili-ya-kitu-cha-nanga" aria-label="Permalink to &quot;Ufafanuzi na Asili ya Asili ya Kitu cha Nanga&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>02</td></tr><tr><td>Moduli</td><td>Kanuni za Jumla na Mipangilio ya Msingi</td></tr><tr><td>Maneno Muhimu</td><td>Kitu cha Nanga, Asili, Ufafanuzi, Asili, Mtandao wa Sheria</td></tr></tbody></table><h2 id="_1-ufafanuzi-wa-msingi-wa-kitu-cha-nanga" tabindex="-1">1. Ufafanuzi wa Msingi wa Kitu cha Nanga <a class="header-anchor" href="#_1-ufafanuzi-wa-msingi-wa-kitu-cha-nanga" aria-label="Permalink to &quot;1. Ufafanuzi wa Msingi wa Kitu cha Nanga&quot;">​</a></h2><p>Kitu cha Nanga ni utaratibu wa msingi na kiumbe cha kuwepo kinachobakilisha usawa wa ulimwengu, kudhibiti mtiririko wa nishati, na kutoa msingi wa mtandao wa usawa katika Cosmos Asili ya Roho Kumi na Elfu na Nanga Iliyosawazishwa. &quot;Nanga&quot; inachukua maana ya thabiti, imara, na isiyoweza kuhama; &quot;Kitu&quot; inachukua maana ya gezo muhimu na kitovu cha muunganisho. Kitu cha Nanga sio mawimbi ya kimwili moja au kitu cha makusanyo ya nishati, bali ni kiumbe cha muundo ambako vipimo vinne vya nyenzo, nishati, fahamu, na sheria vinakutana — udhihirisho na uthibitisho wa sheria ya asili ya ulimwengu katika gezo mahsusi la nafasi-na-wakati.</p><p>Kwa muundo, Kitu cha Nanga kinajengwa kwa sehemu tatu: msingi, ganda, na vipande vya kugusa. Msingi ni kiungo cha kuingia kwenye Mtandao wa Sheria; ganda ni kizuizi cha nishati kinacholinda msingi; na vipande vya kugusa ni njia za muunganisho zinazotua hadi njia na maisha ya karibu. Tatu hizi zinafanya kazi pamoja, kuruhusu Kitu cha Nanga kufanya kwa wakati mmoja kazi tatu za kudhibiti nishati, kupitisha taarifa, na kudhihirisha sheria.</p><h2 id="_2-sifa-za-asili-za-kitu-cha-nanga" tabindex="-1">2. Sifa za Asili za Kitu cha Nanga <a class="header-anchor" href="#_2-sifa-za-asili-za-kitu-cha-nanga" aria-label="Permalink to &quot;2. Sifa za Asili za Kitu cha Nanga&quot;">​</a></h2><p>Asili ya Kitu cha Nanga inaweza kueleweka kutoka vipimo vitatu vifuatavyo:</p><table tabindex="0"><thead><tr><th>Kipimo</th><th>Sifa ya Asili</th><th>Udhihirisho Mahsusi</th></tr></thead><tbody><tr><td>Kipimo cha Sheria</td><td>Gezo thabiti la sheria ya asili</td><td>Kitu cha Nanga ni &quot;nanga&quot; ya sheria ya asili ya ulimwengu katika nafasi-na-wakati, ikitoa sheria inayotiririka mwenendo thabiti wa utendaji</td></tr><tr><td>Kipimo cha Nishati</td><td>Kitovu cha kudhibiti mzunguko wa nishati</td><td>Kitu cha Nanga kinadhibiti mwelekeo na kasi ya mtiririko wa nishati ya ulimwengu, kuzuia nishati kushikiliwa kwa uwindaji au kutawanyika kwa utaratibu</td></tr><tr><td>Kipimo cha Fahamu</td><td>Kiolesura cha kukusanya fahamu ya jumla</td><td>Kitu cha Nanga kinauunganisha fahamu ya kibinafsi na fahamu ya jumla ya ulimwengu, kuruhusu dhamira ya Kabila Kumi na Elfu kukusanywa kuwa mwelekeo wa kawaida wa ustaarabu</td></tr><tr><td>Kipimo cha Nafasi</td><td>Kituo thabiti cha muunganisho kati ya njia</td><td>Kitu cha Nanga ni msingi wa muunganisho thabiti kati ya njia; kusafiri kati ya njia bila Kitu cha Nanga ni hatari na hesiyoweza kudhibitiwa</td></tr><tr><td>Kipimo cha Wakati</td><td>Kiwango cha kupima mstari wa wakati</td><td>Kitu cha Nanga kinatoa mfumo wa kumbukumbu thabiti kwa kurudi nyuma kwa wakati na uchunguzi wa wakati, kuzuia utokeo wa kizingo cha wakati</td></tr></tbody></table><h2 id="_3-uhusiano-kati-ya-kitu-cha-nanga-na-asili" tabindex="-1">3. Uhusiano kati ya Kitu cha Nanga na Asili <a class="header-anchor" href="#_3-uhusiano-kati-ya-kitu-cha-nanga-na-asili" aria-label="Permalink to &quot;3. Uhusiano kati ya Kitu cha Nanga na Asili&quot;">​</a></h2><p>&quot;Asili&quot; ni chanzo cha mwisho na msingi wa kimsingi wa sheria zote, nishati, na maisha katika ulimwengu. Uhusiano kati ya Kitu cha Nanga na Asili unaweza kufupishwa kama uhusiano wa &quot;udhihirisho na mwenendo&quot;:</p><ol><li><strong>Asili ni mwili, Kitu cha Nanga ni kazi</strong>: Asili ni kiumbe cha kimsingi cha ulimwengu, na Kitu cha Nanga ni utaratibu mahsusi ambapo Asili inafanya kazi yake. Bila Asili, Kitu cha Nanga hakiwezi kuanzishwa; bila Kitu cha Nanga, nguvu ya Asili haiwezi kufaa kwa utaratibu kwa wote walio hai.</li><li><strong>Asili ni moja, Kitu cha Nanga ni nyingi</strong>: Asili ni ya pekee na ya umoja, wakati Kitu cha Nanga ni nyingi na zimegawanywa. Vitu vya Nanga vingi pamoja vinajenga Mtandao wa Vitu vya Nanga, na kugawanya nguvu ya Asili ya pekee hadi kila kona ya ulimwengu.</li><li><strong>Asili ni tulivu, Kitu cha Nanga ni hai</strong>: Asili yenyewe ni kiumbe cha mwisho kinachozungumzia harakati na utulivu, wakati Kitu cha Nanga ni mwenendo wa utendaji wa Asili katika ulimwengu wenye harakati. Kuanzisha, kudumisha, kupima, na kuboresha Vitu vya Nanga ni mchakato mahsusi wa kupatanisha nguvu ya Asili na mabadiliko ya ulimwengu.</li></ol><h2 id="_4-uainishaji-na-viwango-vya-vitu-vya-nanga" tabindex="-1">4. Uainishaji na Viwango vya Vitu vya Nanga <a class="header-anchor" href="#_4-uainishaji-na-viwango-vya-vitu-vya-nanga" aria-label="Permalink to &quot;4. Uainishaji na Viwango vya Vitu vya Nanga&quot;">​</a></h2><p>Vitu vya Nanga vimegawanywa katika viwango vifuatavyo kulingana na kazi na eneo la ufunuo:</p><table tabindex="0"><thead><tr><th>Kiwango</th><th>Jina</th><th>Eneo la Ufunuo</th><th>Kazi ya Msingi</th></tr></thead><tbody><tr><td>Kiwango cha Kwanza</td><td>Kitu cha Nanga cha Asili ya Ulimwengu</td><td>Heng Yuan Zhou nzima</td><td>Kubakilisha usawa wa jumla wa ulimwengu, kuwa chanzo cha Vitu vya Nanga vyote</td></tr><tr><td>Kiwango cha Pili</td><td>Kitu cha Nanga cha Msingi wa Njia</td><td>Njia moja</td><td>Kubakilisha utulivu wa utando wa njia, kudhibiti mzunguko wa nishati wa ndani wa njia</td></tr><tr><td>Kiwango cha Tatu</td><td>Kitu cha Nanga cha Eneo la Nyota</td><td>Galaksi au eneo la nyota</td><td>Kuunganisha sayari zote katika eneo la nyota, kudhibiti mtiririko wa nishati wa eneo</td></tr><tr><td>Kiwango cha Nne</td><td>Kitu cha Nanga cha Sayari</td><td>Sayari moja</td><td>Kubakilisha usawa wa mazingira ya sayari, kutoa msingi wa mtandao wa usawa wa kiwango cha sayari</td></tr><tr><td>Kiwango cha Tano</td><td>Kitu cha Nanga cha Ustaarabu</td><td>Eneo moja la makazi ya ustaarabu</td><td>Kuunganisha watu binafsi wa ustaarabu, kutoa msingi wa mzunguko wa mwisho wa usawa wa kiwango cha ustaarabu</td></tr><tr><td>Kiwango cha Sita</td><td>Kitu cha Nanga cha Kibinafsi</td><td>Mtu mmoja</td><td>Nanga ya asili iliyoanzishwa ndani ya mwili wa mzazi, msingi wa mageuzi ya kibinafsi</td></tr></tbody></table><p>Vitu vya Nanga vya kila kiwango vinaunganishana kupitia kanuni ya &quot;kuingia chini, kukusanya juu&quot;: matokeo ya uozi wa Vitu vya Nanga vya chini vinakusanywa juu, na mwisho wa thabiti wa Vitu vya Nanga vya juu unashuka chini kulea. Kitu cha Nanga cha Kibinafsi ni kitu kidogo zaidi cha Mtandao wa Vitu vya Nanga mzima, na msingi wa kidogo cha &quot;Njia kwa Kila Mtu&quot; wa ustaarabu wa usawa.</p><h2 id="_5-kuanzisha-na-kudumisha-vitu-vya-nanga" tabindex="-1">5. Kuanzisha na Kudumisha Vitu vya Nanga <a class="header-anchor" href="#_5-kuanzisha-na-kudumisha-vitu-vya-nanga" aria-label="Permalink to &quot;5. Kuanzisha na Kudumisha Vitu vya Nanga&quot;">​</a></h2><p>Kuanzisha Kitu cha Nanga kinahitaji masharti matatu: gezo linalofaa la nafasi-na-wakati, nishati ya asili inayotosha, na nia ya usawa iliyo wazi. Tatu hizi hazitoweza kukosa. Gezo la nafasi-na-wakati linabaini utulivu wa Kitu cha Nanga, nishati ya asili inabaini nguvu yake, na nia ya usawa inabaini sifa yake — kile kilichoundwa kwa nia ya uwindaji sio Kitu cha Nanga cha kweli, bali mtego wa nishati.</p><p>Kudumisha Vitu vya Nanga kunajumuisha kazi nne za kawaida: kupima mara kwa mara, kuprovishen nishati, kutengeneza vipande vya kugusa, na kuimarisha ganda. Vitu vya Nanga vya kiwango cha juu vinahitaji pia usawazishaji wa sheria na uratibu kati ya njia. Ustaarabu wa usawa umeanzisha mfumo maalum wa walezi wa Vitu vya Nanga, unaoendeshwa na waozaji wa juu wa mfumo wa kudhibiti sheria za nafasi.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kitu cha Nanga ni utaratibu wa msingi wa Heng Yuan Zhou, na msingi wa kimwili na sheria wa ustaarabu wa usawa. Kuelewa ufafanuzi na asili ya Kitu cha Nanga ni kwanza cha kuelewa mfumo mzima wa Ustaarabu wa Usawa wa Nanga. Kitu cha Nanga sio zana baridi ya sheria, bali ni jibu na mwenendo wa asili ya ulimwengu kwa tumaini la usawa la Kabila Kumi na Elfu.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Muhtasari wa Cosmos ya Heng Yuan Zhou)</li><li>20-锚点结构与层级 (Muundo na Viwango vya Vitu vya Nanga)</li><li>24-锚点能量传导路径 (Njia ya Usambazaji wa Nishati ya Kitu cha Nanga)</li></ul>',22)])])}const m=i(h,[["render",s]]);export{g as __pageData,m as default};
